class MockWarehouse : public Warehouse {
 public:
  MOCK_METHOD(bool, hasInventory, (const std::string&, int), (override));
};

TEST(OrderTest, ReportsOutOfStock) {
  MockWarehouse warehouse;
  ON_CALL(warehouse, hasInventory(_, _)).WillByDefault(Return(false));
  EXPECT_FALSE(Order("Talisker", 50).fill(warehouse));
}

